import{_ as n,C as l,o as e,c as s,j as t,E as r,a as o,a2 as d}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse(`{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"n":3,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":7,"title":"Axure RP: Dinamik panellar va interaktiv bog'lanishlar (Interactions)","lead":"Statik chizmalardan chertiladigan (clickable) prototiplarga o'tish, Dinamik panellar va sahifalararo navigatsiya sirlari.","link":"/mentor/9-sinf/hafta-03/dars-1","slide":"/slaydlar/9-sinf/hafta-03/dars-1.html","test":"/slaydlar/9-sinf/hafta-03/dars-1-test.html"},{"g":8,"title":"Foydalanuvchi formalari, kiritish maydonlari va xatoliklar dizayni (Form Wireframing)","lead":"Kiritish elementlari (Input, Dropdown, Radio, Checkbox), maydon holatlari, inline validation va xatoliklardan qutqaruvchi qulay interfeyslar.","link":"/mentor/9-sinf/hafta-03/dars-2","slide":"/slaydlar/9-sinf/hafta-03/dars-2.html","test":"/slaydlar/9-sinf/hafta-03/dars-2-test.html"},{"g":9,"title":"Wireframe loyihasini yakunlash, annotatsiyalar va Figmaga eksport","lead":"Izohli simli ramkalar (Annotated wireframes), PNG/SVG/PDF eksport va Figmada UI dizayn uchun referens qatlamini sozlash.","link":"/mentor/9-sinf/hafta-03/dars-3","slide":"/slaydlar/9-sinf/hafta-03/dars-3.html","test":"/slaydlar/9-sinf/hafta-03/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf/hafta-03/index.md","filePath":"mentor/9-sinf/hafta-03/index.md"}`),h={name:"mentor/9-sinf/hafta-03/index.md"},m={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},k={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function c(y,a,b,f,v,p){const i=l("Icon");return e(),s("div",null,[t("div",m,[t("h2",u,[r(i,{name:"house"}),a[0]||(a[0]=o(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Natijalarni daftarda yoki dizayn dasturida (Axure RP, Balsamiq, Figma) alohida papkada saqlang. Topshirish: keyingi dars boshida mentorga ko&#39;rsating.</p><h2 id="_7-dars-uchun-axure-rp-dinamik-panellar-va-interaksiyalar" tabindex="-1">7-dars uchun (Axure RP: Dinamik panellar va interaksiyalar) <a class="header-anchor" href="#_7-dars-uchun-axure-rp-dinamik-panellar-va-interaksiyalar" aria-label="Permalink to &quot;7-dars uchun (Axure RP: Dinamik panellar va interaksiyalar)&quot;">​</a></h2><p><strong>1-topshiriq: «Chertiladigan kitob kartasi va tablar»</strong> (20–25 daqiqa)</p><ol><li>Axure RP (yoki bepul interaktiv analog)da 2 ta sahifa yarating: <code>Home_books</code> va <code>Book_details</code>.</li><li><code>Home_books</code>dagi kitob kartasiga <code>OnClick</code> hodisasi orqali <code>Open Link</code> → <code>Book_details</code> amalini biriktiring.</li><li><code>Book_details</code> sahifasida Dynamic Panel yarating va 2 ta State hosil qiling («Annotatsiya» va «Kitob haqida fikrlar»).</li><li>Yuqoridagi 2 ta tugmaga <code>Set Panel State</code> amalini bog&#39;lab, tablarni bir-biriga almashtiruvchi interaktivlikni sozlang.</li><li>Loyihani Preview rejimida brauzerda tekshiring.</li></ol><p><strong>Kutiladigan natija:</strong> sahifalararo o&#39;tuvchi va bitta ekranda tablarni yangilaydigan ishchi interaktiv prototip. <strong>Nimani topshirasiz:</strong> prototipning qisqa video-yozuvi (screen record) yoki dastur fayli (<code>.rp</code>).</p><h2 id="_8-dars-uchun-formalar-kiritish-maydonlari-va-xatoliklar-dizayni" tabindex="-1">8-dars uchun (Formalar, kiritish maydonlari va xatoliklar dizayni) <a class="header-anchor" href="#_8-dars-uchun-formalar-kiritish-maydonlari-va-xatoliklar-dizayni" aria-label="Permalink to &quot;8-dars uchun (Formalar, kiritish maydonlari va xatoliklar dizayni)&quot;">​</a></h2><p><strong>2-topshiriq: «Ro&#39;yxatdan o&#39;tish formasi va Error State»</strong> (20–30 daqiqa)</p><ol><li>«E-kutubxona» uchun ro&#39;yxatdan o&#39;tish formasining to&#39;liq wireframe&#39;ini chizing (Label, Input, Placeholder, Helper text va Submit tugmasi).</li><li>Quyidagi kiritish turlarini to&#39;g&#39;ri ishlating: <ul><li>To&#39;liq ism (<code>Text Field</code>);</li><li>Parol (<code>Password Field</code> + ko&#39;zcha);</li><li>Sevimli janrlar (<code>Checkbox</code> — kamida 3 ta variant);</li><li>Bildirishnomalarni olish usuli (<code>Radio Button</code> — Email / SMS).</li></ul></li><li>Ushbu formaning «Xatolik holati» (Error state)ni alohida chizing: noto&#39;g&#39;ri email kiritilganda maydon qanday ko&#39;rinishi va tagidagi mikro-matn qanday yozilishini ko&#39;rsating.</li></ol><p><strong>Kutiladigan natija:</strong> barcha element turlari to&#39;g&#39;ri tanlangan toza forma wireframe&#39;i va uning xatolik holati. <strong>Nimani topshirasiz:</strong> 2 ta ekran skrinshoti (boshlang&#39;ich holat va xatolik holati).</p><h2 id="_9-dars-uchun-wireframe-loyihasini-yakunlash-va-figmaga-eksport" tabindex="-1">9-dars uchun (Wireframe loyihasini yakunlash va Figmaga eksport) <a class="header-anchor" href="#_9-dars-uchun-wireframe-loyihasini-yakunlash-va-figmaga-eksport" aria-label="Permalink to &quot;9-dars uchun (Wireframe loyihasini yakunlash va Figmaga eksport)&quot;">​</a></h2><p><strong>3-topshiriq: «E-kutubxona to&#39;liq karkasi va Figma referens qatlami»</strong> (25–30 daqiqa)</p><ol><li>Hafta davomida yaratilgan barcha ekranlarni (<code>Home_books</code>, <code>Book_details</code>, <code>Register_modal</code>) tekshiring va kamida 3 ta blok ustiga raqamli annotatsiya (texnik izoh) yozing.</li><li>Loyihani toza PNG formatida eksport qiling.</li><li>Figma dasturida <code>Desktop 1440</code> o&#39;lchamli Frame ochib, ushbu PNG rasmni joylang, Opacity darajasini <code>40%</code> ga tushiring va qatlamni qulflang (<code>Lock</code>).</li><li>Qulflangan karkas ustidan bitta kitob kartasining birinchi rangli UI variantini (fon, rasm o&#39;rni, chiroyli tugma) chizib ko&#39;ring.</li></ol><p><strong>Kutiladigan natija:</strong> dasturchilar uchun annotatsiyalangan wireframe va Figmada UI dizayn uchun tayyorlangan referens qatlam. <strong>Nimani topshirasiz:</strong> Figmadagi loyiha havolasi (link) yoki eksport qilingan skrinshot.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Dars boshida o&#39;quvchilarning Dynamic Panel yordamida tablarni almashtirishini ko&#39;rib chiqing. Formalarda <code>Placeholder</code> va <code>Label</code> aralashib ketmaganligiga e&#39;tibor qarating. 9-dars vazifasida Figmaga import qilingan rasm chindan ham qulflanganligini va ustidan toza vektor elementlar chizilganini tekshiring.</p>',15))]),t("div",k,[t("h2",g,[r(i,{name:"list-checks"}),a[3]||(a[3]=o(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p><strong>Shkala haqida.</strong> 100 ballik shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>. Guruhdagi o&#39;quvchilar soni belgilanmagan, shuning uchun 3 ta bo&#39;sh qatorli shablon berilgan (mentor o&#39;zgartirishi mumkin).</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mavzu mohiyatini tushunadi va aytib bera oladi (tezkor nazorat)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri, mantiqiy va to&#39;liq bajarilgan</td><td>30</td></tr><tr><td>Dizayn mantig&#39;i: interaksiyalar, formalar validatsiyasi, annotatsiyalar tozaligi</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><hr><h2 id="_7-dars-axure-rp-dinamik-panellar-va-interaksiyalar" tabindex="-1">7-dars (Axure RP: Dinamik panellar va interaksiyalar) <a class="header-anchor" href="#_7-dars-axure-rp-dinamik-panellar-va-interaksiyalar" aria-label="Permalink to &quot;7-dars (Axure RP: Dinamik panellar va interaksiyalar)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: <code>OnClick</code> → <code>Open Link</code> to&#39;g&#39;ri ishlashi; Dynamic Panel yaratish va 2 ta State o&#39;rtasida <code>Set Panel State</code> orqali tablarni almashtirish.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dizayn mantig&#39;i /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="_8-dars-formalar-kiritish-maydonlari-va-xatoliklar-dizayni" tabindex="-1">8-dars (Formalar, kiritish maydonlari va xatoliklar dizayni) <a class="header-anchor" href="#_8-dars-formalar-kiritish-maydonlari-va-xatoliklar-dizayni" aria-label="Permalink to &quot;8-dars (Formalar, kiritish maydonlari va xatoliklar dizayni)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: Label va Placeholder to&#39;g&#39;ri ajratilgani; Radio va Checkbox farqlanishi; Error state va inline validation mikro-matnlari.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dizayn mantig&#39;i /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="_9-dars-wireframe-loyihasini-yakunlash-va-figmaga-eksport" tabindex="-1">9-dars (Wireframe loyihasini yakunlash va Figmaga eksport) <a class="header-anchor" href="#_9-dars-wireframe-loyihasini-yakunlash-va-figmaga-eksport" aria-label="Permalink to &quot;9-dars (Wireframe loyihasini yakunlash va Figmaga eksport)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: Texnik annotatsiyalar (raqamli markerlar); PNG/SVG eksport; Figmada 40% Opacity bilan referens qatlamini qulflash.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dizayn mantig&#39;i /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="hafta-yakuni-va-i-bob-xulosasi" tabindex="-1">Hafta yakuni va I bob xulosasi <a class="header-anchor" href="#hafta-yakuni-va-i-bob-xulosasi" aria-label="Permalink to &quot;Hafta yakuni va I bob xulosasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>7-dars</th><th>8-dars</th><th>9-dars</th><th>O&#39;rtacha</th><th>Baho</th><th>Izoh (kuchli/zaif tomonlari)</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-uchun-xulosa" tabindex="-1">Mentor uchun xulosa <a class="header-anchor" href="#mentor-uchun-xulosa" aria-label="Permalink to &quot;Mentor uchun xulosa&quot;">​</a></h2><p>O&#39;quvchilar I-bobning «Wireframing va prototiplash» blokini to&#39;liq yakunlashdi. Ular axborot arxitekturasi, monoxrom karkas chizish, interaktiv prototip yasash va dasturchilar uchun annotatsiya tuzishni o&#39;rgandilar. Keyingi 4-haftadan boshlab II bo&#39;lim — UI dizayn asoslari (rang g&#39;ildiragi, kontrast, tipografiya, vizual ierarxiya va kompozitsiya) boshlanadi.</p>',21))])])}const x=n(h,[["render",c]]);export{z as __pageData,x as default};
